import test from 'node:test';
import assert from 'node:assert/strict';
import { rotate } from '../src/rotate.js';

const cases = [
  { name: 'right by one', input: [1, 2, 3, 4], steps: 1, expected: [4, 1, 2, 3], snapshot: [1, 2, 3, 4] },
  { name: 'right by two', input: [1, 2, 3, 4], steps: 2, expected: [3, 4, 1, 2], snapshot: [1, 2, 3, 4] },
  { name: 'right by three', input: [1, 2, 3, 4], steps: 3, expected: [2, 3, 4, 1], snapshot: [1, 2, 3, 4] },
  { name: 'zero steps', input: [1, 2, 3, 4], steps: 0, expected: [1, 2, 3, 4], snapshot: [1, 2, 3, 4] },
  { name: 'one full turn', input: [1, 2, 3, 4], steps: 4, expected: [1, 2, 3, 4], snapshot: [1, 2, 3, 4] },
  { name: 'steps exceeding length', input: [1, 2, 3, 4], steps: 6, expected: [3, 4, 1, 2], snapshot: [1, 2, 3, 4] },
  { name: 'repeated values preserve order', input: ['a', 'b', 'a', 'c', 'b'], steps: 2, expected: ['c', 'b', 'a', 'b', 'a'], snapshot: ['a', 'b', 'a', 'c', 'b'] },
  { name: 'singleton at zero steps', input: [7], steps: 0, expected: [7], snapshot: [7] },
  { name: 'singleton at positive steps', input: [7], steps: 9, expected: [7], snapshot: [7] },
  { name: 'empty at zero steps', input: [], steps: 0, expected: [], snapshot: [] },
  { name: 'empty at positive steps', input: [], steps: 9, expected: [], snapshot: [] },
];

for (const { name, input, steps, expected, snapshot } of cases) {
  test(name, () => {
    const result = rotate(input, steps);
    assert.ok(Array.isArray(result));
    assert.deepStrictEqual(result, expected);
    assert.notStrictEqual(result, input);
    assert.deepStrictEqual(input, snapshot);

    if (result.length > 0) result[0] = 'changed';
    result.push('appended');
    assert.deepStrictEqual(input, snapshot, 'mutating the returned array must leave the input unchanged');
  });
}

const nonArrays = [
  { name: 'null', value: null },
  { name: 'undefined', value: undefined },
  { name: 'string', value: 'abc' },
  { name: 'number', value: 42 },
  { name: 'plain object', value: {} },
  { name: 'array-like object', value: { 0: 'a', 1: 'b', length: 2 } },
];

for (const { name, value } of nonArrays) {
  test(`rejects non-array input: ${name}`, () => {
    assert.throws(() => rotate(value, 1), TypeError);
  });
}

for (const steps of [-1, -4, 0.5, 1.5, -0.5, -1.5]) {
  test(`rejects invalid steps ${steps} for a populated array`, () => {
    const input = [1, 2, 3, 4];
    assert.throws(() => rotate(input, steps), RangeError);
    assert.deepStrictEqual(input, [1, 2, 3, 4]);
  });

  test(`rejects invalid steps ${steps} for an empty array`, () => {
    const input = [];
    assert.throws(() => rotate(input, steps), RangeError);
    assert.deepStrictEqual(input, []);
  });
}

